def list_invoices(
    sort_by: str = Query(
        "created_at", pattern=rf"^({'|'.join(ALLOWED_SORT_COLUMNS)})$"
    ),
    order: str = Query("desc", pattern=rf"^({'|'.join(ALLOWED_ORDERS)})$"),
    status: Optional[str] = None,
    x_tenant_id: int = Header(...),
    db=Depends(get_db),
):
    if sort_by not in ALLOWED_SORT_COLUMNS:
        # Defensive: Query pattern already rejects these, but stay explicit.
        raise ValueError(f"Invalid sort_by: {sort_by}")
    if order not in ALLOWED_ORDERS:
        raise ValueError(f"Invalid order: {order}")

    params = {"tenant": x_tenant_id}
    status_clause = ""
