        f"WHERE tenant_id = :tenant {status_clause} ORDER BY {sort_by} {direction}"
    )
    rows = db.execute(query, params).mappings().all()
    return [
        {**row, "created_at": row["created_at"].isoformat()}
        for row in rows
    ]

